    assertEquals(columnName, iRowMeta.getValueMeta(0).getName());
    assertEquals(columnType, iRowMeta.getValueMeta(0).getOriginalColumnTypeName());
    assertEquals(columnSize, iRowMeta.getValueMeta(0).getLength());
}

